				bool okA = Verify(_ciphers!, _salt, _tag, out KeySet rkA);
				bool okB = Verify(_ciphersB!, _saltB, _tagB, out KeySet rkB);
				if (okA && okB)
				{
					return Decode(_salt, _ciphers!, rkA);
				}
				if (okA || okB)
				{
					string recovered = okA
						? Decode(_salt, _ciphers!, rkA)
						: Decode(_saltB, _ciphersB!, rkB);
					// Heal the damaged copy from the recovered plaintext (fresh
					// salt), mirroring the load path — heal before raising so a
					// handler re-reading sees a healthy value.
					if (okA)
					{
						_saltB = Vault.RandomSalt();
						SealBackupStore(recovered, backup: true);
					}
					else
					{
						_salt = Vault.RandomSalt();
						SealBackupStore(recovered, backup: false);
					}
					TamperingNotifier.Raise();
					return recovered;
				}
				Vault.ThrowTampered();
				return string.Empty;
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private string DecryptedInline()
		{
			Span<ulong> a = stackalloc ulong[InlineCapacity / 4];
			Span<ulong> b = stackalloc ulong[InlineCapacity / 4];
			CopyInlineWords(a, backup: false);
			CopyInlineWords(b, backup: true);
			bool okA = VerifyInline(_length, a, _salt, _tag, out KeySet rkA);
			bool okB = VerifyInline(_length, b, _saltB, _tagB, out KeySet rkB);
			if (okA && okB)
			{
				return DecodeInlineString(_salt, a, rkA);
			}
			if (okA || okB)
			{
				string recovered = okA
					? DecodeInlineString(_salt, a, rkA)
					: DecodeInlineString(_saltB, b, rkB);
				if (okA)
				{
					_saltB = Vault.RandomSalt();
					SealBackupStore(recovered, backup: true);
				}
				else
				{
					_salt = Vault.RandomSalt();
					SealBackupStore(recovered, backup: false);
				}
				TamperingNotifier.Raise();
				return recovered;
			}
			Vault.ThrowTampered();
			return string.Empty;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private string DecodeInlineString(ulong salt, ReadOnlySpan<ulong> words, in KeySet rk)
		{
			Span<char> plain = stackalloc char[InlineCapacity];
			DecodeWords(rk, salt, words, _length, plain);
			return new string(plain.Slice(0, _length));
		}

		/// <summary>Tries to decrypt without throwing. Returns false when never assigned or tampered; tampering still raises <see cref="TamperingNotifier.TamperingDetected"/>.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public bool TryDecrypt([NotNullWhen(true)] out string value)
		{
			if (_mode == StorageMode.Unassigned || !StoreIsCoherent())
			{
				value = default!;
				return false;
			}
			if (_length == 0)
			{
				value = string.Empty;
				return true;
			}
			if (_mode == StorageMode.Inline)
			{
				return TryDecryptInline(out value);
			}
			bool okA = Verify(_ciphers!, _salt, _tag, out KeySet rkA);
			bool okB = Verify(_ciphersB!, _saltB, _tagB, out KeySet rkB);
			if (okA && okB)
			{
				value = Decode(_salt, _ciphers!, rkA);
				return true;
			}
			if (okA || okB)
			{
				value = okA ? Decode(_salt, _ciphers!, rkA) : Decode(_saltB, _ciphersB!, rkB);
				if (okA)
				{
					_saltB = Vault.RandomSalt();
					SealBackupStore(value, backup: true);
				}
				else
				{
					_salt = Vault.RandomSalt();
					SealBackupStore(value, backup: false);
				}
				TamperingNotifier.Raise();
				return true;
			}
			TamperingNotifier.Raise();
			value = default!;
			return false;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private bool TryDecryptInline(out string value)
		{
			Span<ulong> a = stackalloc ulong[InlineCapacity / 4];
			Span<ulong> b = stackalloc ulong[InlineCapacity / 4];
			CopyInlineWords(a, backup: false);
			CopyInlineWords(b, backup: true);
			bool okA = VerifyInline(_length, a, _salt, _tag, out KeySet rkA);
			bool okB = VerifyInline(_length, b, _saltB, _tagB, out KeySet rkB);
			if (okA && okB)
			{
				value = DecodeInlineString(_salt, a, rkA);
				return true;
			}
			if (okA || okB)
			{
				value = okA
					? DecodeInlineString(_salt, a, rkA)
					: DecodeInlineString(_saltB, b, rkB);
				if (okA)
				{
					_saltB = Vault.RandomSalt();
					SealBackupStore(value, backup: true);
				}
				else
				{
					_salt = Vault.RandomSalt();
					SealBackupStore(value, backup: false);
				}
				TamperingNotifier.Raise();
				return true;
			}
			TamperingNotifier.Raise();
			value = default!;
			return false;
		}

		/// <summary>Copies the decrypted characters into the destination span without allocating. The destination must hold at least <see cref="Length"/> characters. No-op when never assigned; throws when tampered, with the same semantics as <see cref="Decrypted"/>.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public void CopyTo(Span<char> destination)
		{
			if (_mode == StorageMode.Unassigned)
			{
				return;
			}
			if (!StoreIsCoherent())
			{
				Vault.ThrowTampered();
			}
			if (destination.Length < _length)
			{
				throw new ArgumentException("Destination too short.", nameof(destination));
			}
			if (_length == 0)
			{
				return;
			}
			if (_mode == StorageMode.Inline)
			{
				CopyToInline(destination);
				return;
			}
			bool okA = Verify(_ciphers!, _salt, _tag, out KeySet rkA);
			bool okB = Verify(_ciphersB!, _saltB, _tagB, out KeySet rkB);
			if (okA && okB)
			{
				DecodeInto(rkA, _salt, _ciphers!, destination);
				return;
			}
			if (okA || okB)
			{
				if (okA)
				{
					DecodeInto(rkA, _salt, _ciphers!, destination);
				}
				else
				{
					DecodeInto(rkB, _saltB, _ciphersB!, destination);
				}
				// Heal the damaged array from the just-decoded destination span.
				ReadOnlySpan<char> plain = destination.Slice(0, _length);
				if (okA)
				{
					_saltB = Vault.RandomSalt();
					(_ciphersB, _tagB) = SealWords(plain, _length, _saltB);
				}
				else
				{
					_salt = Vault.RandomSalt();
					(_ciphers, _tag) = SealWords(plain, _length, _salt);
				}
				TamperingNotifier.Raise();
				return;
			}
			Vault.ThrowTampered();
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private void CopyToInline(Span<char> destination)
		{
			Span<ulong> a = stackalloc ulong[InlineCapacity / 4];
			Span<ulong> b = stackalloc ulong[InlineCapacity / 4];
			CopyInlineWords(a, backup: false);
			CopyInlineWords(b, backup: true);
			bool okA = VerifyInline(_length, a, _salt, _tag, out KeySet rkA);
			bool okB = VerifyInline(_length, b, _saltB, _tagB, out KeySet rkB);
			if (okA && okB)
			{
				DecodeInto(rkA, _salt, a, destination);
				return;
			}
			if (okA || okB)
			{
				if (okA)
				{
					DecodeInto(rkA, _salt, a, destination);
				}
				else
				{
					DecodeInto(rkB, _saltB, b, destination);
				}
				ResealInlineBackup(destination.Slice(0, _length), backup: okA);
				TamperingNotifier.Raise();
				return;
			}
			Vault.ThrowTampered();
		}

		/// <summary>
		/// Tries to copy the decrypted characters into the destination span without
		/// allocating and without throwing. Returns false (writing nothing) when never
		/// assigned, doubly tampered, or the destination is too short; tampering still
		/// raises <see cref="TamperingNotifier.TamperingDetected"/>. A singly-tampered
		/// value recovers, heals, and returns true like <see cref="CopyTo"/>.
		/// </summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public bool TryCopyTo(Span<char> destination, out int charsWritten)
		{
			if (_mode == StorageMode.Unassigned || !StoreIsCoherent())
			{
				charsWritten = 0;
				return false;
			}
			if (destination.Length < _length)
			{
				charsWritten = 0;
				return false;
			}
			if (_length == 0)
			{
				charsWritten = 0;
				return true;
			}
			return _mode == StorageMode.Inline
				? TryCopyToInline(destination, out charsWritten)
				: TryCopyToHeap(destination, out charsWritten);
		}

		private bool TryCopyToHeap(Span<char> destination, out int charsWritten)
		{
			bool okA = Verify(_ciphers!, _salt, _tag, out KeySet rkA);
			bool okB = Verify(_ciphersB!, _saltB, _tagB, out KeySet rkB);
			if (okA && okB)
			{
				DecodeInto(rkA, _salt, _ciphers!, destination);
				charsWritten = _length;
				return true;
			}
			if (okA || okB)
			{
				if (okA)
				{
					DecodeInto(rkA, _salt, _ciphers!, destination);
				}
				else
				{
					DecodeInto(rkB, _saltB, _ciphersB!, destination);
				}
				ReadOnlySpan<char> plain = destination.Slice(0, _length);
				if (okA)
				{
					_saltB = Vault.RandomSalt();
					(_ciphersB, _tagB) = SealWords(plain, _length, _saltB);
				}
				else
				{
					_salt = Vault.RandomSalt();
					(_ciphers, _tag) = SealWords(plain, _length, _salt);
				}
				TamperingNotifier.Raise();
				charsWritten = _length;
				return true;
			}
			TamperingNotifier.Raise();
			charsWritten = 0;
			return false;
		}

		private bool TryCopyToInline(Span<char> destination, out int charsWritten)
		{
			Span<ulong> a = stackalloc ulong[InlineCapacity / 4];
			Span<ulong> b = stackalloc ulong[InlineCapacity / 4];
			CopyInlineWords(a, backup: false);
			CopyInlineWords(b, backup: true);
			bool okA = VerifyInline(_length, a, _salt, _tag, out KeySet rkA);
			bool okB = VerifyInline(_length, b, _saltB, _tagB, out KeySet rkB);
			if (okA && okB)
			{
				DecodeInto(rkA, _salt, a, destination);
				charsWritten = _length;
				return true;
			}
			if (okA || okB)
			{
				if (okA)
				{
					DecodeInto(rkA, _salt, a, destination);
				}
				else
				{
					DecodeInto(rkB, _saltB, b, destination);
				}
				ResealInlineBackup(destination.Slice(0, _length), backup: okA);
				TamperingNotifier.Raise();
				charsWritten = _length;
				return true;
			}
			TamperingNotifier.Raise();
			charsWritten = 0;
			return false;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private void DecodeInto(
			in KeySet rk,
			ulong salt,
			ReadOnlySpan<ulong> ciphers,
			Span<char> destination
		)
		{
			DecodeWords(rk, salt, ciphers, _length, destination);
		}

		/// <summary>Parses a string into its secured form.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static SecureString Parse(string? value, IFormatProvider? provider) =>
			new SecureString(value ?? string.Empty);

		/// <summary>Tries to parse a string into its secured form (never fails).</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static bool TryParse(
			string? value,
			IFormatProvider? provider,
			out SecureString result
		)
		{
			result = new SecureString(value ?? string.Empty);
			return true;
		}

		/// <summary>Parses a character span into its secured form, sealing straight from the span.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static SecureString Parse(ReadOnlySpan<char> value, IFormatProvider? provider) =>
			SealSpan(value);

		/// <summary>Tries to parse a character span into its secured form, sealing straight from the span (never fails).</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static bool TryParse(
			ReadOnlySpan<char> value,
			IFormatProvider? provider,
			out SecureString result
		)
		{
			result = SealSpan(value);
			return true;
		}

		/// <summary>Constructs a wrapper sealing directly from characters (no intermediate string).</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private static SecureString SealSpan(ReadOnlySpan<char> value)
		{
			SecureString result = default;
			result.SealAll(value);
			return result;
		}

#if NET7_0_OR_GREATER
		/// <summary>Parses a string into its secured form (explicit parsing).</summary>
