		static SecureString System.ISpanParsable<SecureString>.Parse(
			ReadOnlySpan<char> s,
			IFormatProvider? provider
		) => Parse(s, provider);

		/// <summary>Tries to parse a character span into its secured form (explicit parsing).</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		static bool System.ISpanParsable<SecureString>.TryParse(
			ReadOnlySpan<char> s,
