		/// <summary>
		/// Decrypts onto the stack and invokes the action without ever throwing for
		/// tamper/corruption: returns <c>false</c> (writing nothing observable) when
		/// never assigned or doubly tampered, <c>true</c> otherwise. A singly-tampered
		/// value recovers, heals, and returns <c>true</c> (tampering still raises
		/// <see cref="TamperingNotifier.TamperingDetected"/>). The buffer is zeroed
		/// before this method returns — even when the action throws. Exceptions thrown
		/// by the action itself still propagate.
		/// </summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public bool TryStackDecrypt(DecryptedSpanAction action)
		{
			if (action is null)
			{
				throw new ArgumentNullException(nameof(action));
			}
			Span<char> buffer = stackalloc char[_length];
			if (!TryCopyTo(buffer, out _))
			{
				CryptographicOperations.ZeroMemory(MemoryMarshal.AsBytes(buffer));
				return false;
			}
			try
			{
				action(buffer);
				return true;
			}
			finally
			{
				CryptographicOperations.ZeroMemory(MemoryMarshal.AsBytes(buffer));
			}
		}

		/// <summary>
		/// Decrypts onto the stack and returns the function result via
		/// <paramref name="result"/>. Returns <c>false</c> (with
		/// <paramref name="result"/> set to its default) when never assigned or
		/// doubly tampered — no exception-unwinding cost on the tampered path. A
		/// singly-tampered value recovers, heals, and returns <c>true</c> (tampering
		/// still raises <see cref="TamperingNotifier.TamperingDetected"/>). The buffer
		/// is zeroed before this method returns — even when the function throws.
		/// </summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public bool TryStackDecrypt<TResult>(DecryptedSpanFunc<TResult> func, out TResult result)
		{
			if (func is null)
			{
				throw new ArgumentNullException(nameof(func));
			}
			Span<char> buffer = stackalloc char[_length];
			if (!TryCopyTo(buffer, out _))
			{
				CryptographicOperations.ZeroMemory(MemoryMarshal.AsBytes(buffer));
				result = default!;
				return false;
			}
			try
			{
				result = func(buffer);
				return true;
			}
			finally
			{
				CryptographicOperations.ZeroMemory(MemoryMarshal.AsBytes(buffer));
			}
		}

		/// <summary>
		/// Stateful decrypts onto the stack and returns the function result via
		/// <paramref name="result"/>. Returns <c>false</c> when never assigned or
		/// doubly tampered (see <see cref="TryStackDecrypt{TResult}(DecryptedSpanFunc{TResult}, out TResult)"/>).
		/// Use a <c>static</c> lambda with explicit <paramref name="state"/> to stay
		/// allocation-free. The buffer is zeroed before this method returns — even
		/// when the function throws.
		/// </summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public bool TryStackDecrypt<TState, TResult>(
			TState state,
			DecryptedSpanFunc<TState, TResult> func,
			out TResult result
		)
		{
			if (func is null)
			{
				throw new ArgumentNullException(nameof(func));
			}
			Span<char> buffer = stackalloc char[_length];
			if (!TryCopyTo(buffer, out _))
			{
				CryptographicOperations.ZeroMemory(MemoryMarshal.AsBytes(buffer));
				result = default!;
				return false;
			}
			try
			{
				result = func(buffer, state);
				return true;
			}
			finally
			{
				CryptographicOperations.ZeroMemory(MemoryMarshal.AsBytes(buffer));
			}
		}

		/// <summary>
		/// Stateful decrypts onto the stack and invokes the action without ever throwing
		/// for tamper/corruption: returns <c>false</c> when never assigned or doubly
		/// tampered, <c>true</c> otherwise (see
		/// <see cref="TryStackDecrypt(DecryptedSpanAction)"/>). Use a <c>static</c>
		/// lambda with explicit <paramref name="state"/> to stay allocation-free. The
		/// buffer is zeroed before this method returns — even when the action throws.
		/// </summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public bool TryStackDecrypt<TState>(TState state, DecryptedSpanAction<TState> action)
		{
			if (action is null)
			{
				throw new ArgumentNullException(nameof(action));
			}
			Span<char> buffer = stackalloc char[_length];
			if (!TryCopyTo(buffer, out _))
			{
				CryptographicOperations.ZeroMemory(MemoryMarshal.AsBytes(buffer));
				return false;
			}
			try
			{
				action(buffer, state);
				return true;
			}
			finally
			{
				CryptographicOperations.ZeroMemory(MemoryMarshal.AsBytes(buffer));
			}
		}

		/// <summary>Compares this value with another object for equality.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public override bool Equals(object? obj) => obj is SecureString other && Equals(other);

		/// <summary>Compares this value with another secured string. Unset reads as empty.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public int CompareTo(SecureString other) =>
			(Decrypted ?? string.Empty).CompareTo(other.Decrypted ?? string.Empty);

		/// <summary>Compares this value with another object.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public int CompareTo(object? obj) =>
			obj is SecureString other
				? CompareTo(other)
				: throw new ArgumentException("Object must be of type SecureString.", nameof(obj));

		/// <summary>Returns the hash code of the decrypted value.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public override int GetHashCode()
		{
			string s = Decrypted ?? string.Empty;
			unchecked
			{
				int hash = 17;
				for (int i = 0; i < s.Length; i++)
				{
					hash = hash * 31 + s[i];
				}
				return hash;
			}
		}

		/// <summary>Returns the decrypted value as a string. Empty when never assigned.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public override string ToString() => Decrypted ?? string.Empty;

		/// <summary>Tests two secured string values for equality.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static bool operator ==(SecureString left, SecureString right) => left.Equals(right);

		/// <summary>Tests two secured string values for inequality.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static bool operator !=(SecureString left, SecureString right) =>
			!left.Equals(right);

		/// <summary>Converts a plain string value into its secured form.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static implicit operator SecureString(string value) => new SecureString(value);

		/// <summary>
		/// Secures the characters directly from the span — no intermediate string.
		/// Seals immediately (same cost as any other write); values over 16 characters
		/// allocate their heap backing store, like every other write path.
		/// </summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static implicit operator SecureString(ReadOnlySpan<char> value) => SealSpan(value);

		/// <summary>
		/// Secures the characters directly from the span — no intermediate string.
		/// A separate overload from the <c>ReadOnlySpan</c> conversion because
		/// operator lookup does not chain the <c>Span</c>-to-<c>ReadOnlySpan</c> step:
		/// without this, stackalloc buffers would fail to bind. Same sealing semantics.
		/// </summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static implicit operator SecureString(Span<char> value) => SealSpan(value);

		/// <summary>Converts back to the plain string value (decrypts on read). Null when never assigned.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static implicit operator string?(SecureString value) => value.Decrypted;

		/// <summary>Concatenates two secured string values. Unset reads as empty.</summary>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static SecureString operator +(SecureString a, SecureString b) =>
			new SecureString((a.Decrypted ?? string.Empty) + (b.Decrypted ?? string.Empty));
	}
}
